#!/usr/bin/env bash
# PreToolUse hook — blocks Edit/Write to src/db/migrations/*.sql.
#
# v4 migrations are generated by `drizzle-kit generate` from schema
# edits. Hand-editing the SQL files drifts from the generator: the
# next `db:generate` run produces irreproducible state and may
# overwrite the manual edits.
#
# Receives a single JSON argument on stdin from Claude Code:
#   { "tool_name": "Edit" | "Write", "tool_input": { "file_path": "..." } }
#
# Exit codes:
#   0    allow the tool call
#   2    block with a message printed to stderr (Claude sees this)

set -euo pipefail

input="$(cat)"

# Cheap path filter — doesn't shell-out to jq if the input doesn't
# even mention migrations.
case "$input" in
  *"src/db/migrations/"*".sql"*) ;;
  *) exit 0 ;;
esac

# Now actually parse the path. jq is widely available; fall back to
# python if not.
if command -v jq >/dev/null 2>&1; then
  path="$(printf '%s' "$input" | jq -r '.tool_input.file_path // empty')"
else
  path="$(printf '%s' "$input" | python3 -c 'import json,sys; d=json.load(sys.stdin); print(d.get("tool_input",{}).get("file_path",""))')"
fi

case "$path" in
  *"src/db/migrations/"*".sql")
    cat <<'MSG' >&2
ship-api PreToolUse: blocking edit to drizzle migration SQL.

v4 migrations are emitted by `drizzle-kit generate` from schema source.
Hand-editing the SQL drifts from the generator and silently breaks
reproducibility:

  1. Edit the schema source (your module's `schema.ts`) instead
  2. Run `npm run db:generate -- --name <description>`
  3. Review the generated SQL diff
  4. Commit the schema change + the new migration in the same commit

If you genuinely need to edit a migration manually (rare — fixing a
bad rename detection, e.g.), drop into `! npm run db:generate` from
the prompt and hand-craft the new migration as the next file. Don't
edit existing committed migrations in place.
MSG
    exit 2
    ;;
esac

exit 0
